import React, { useState } from 'react';
import StudentList from './components/StudentList';
import StudentForm from './components/StudentForm';
import StudentDetails from './components/StudentDetails';
import * as studentService from './services/studentService';

export default function App(){
  const [students, setStudents] = useState([]); // loaded via Load Students button
  const [mode, setMode] = useState('list'); // 'list' | 'form' | 'details'
  const [selected, setSelected] = useState(null); // student object or null
  const [formMode, setFormMode] = useState('add'); // 'add' or 'edit'

  const loadStudents = () => {
    studentService.getStudents()
      .then(data => setStudents(data))
      .catch(err => { alert('Failed to load students'); console.error(err) });
  };

  const handleAddClick = () => {
    setFormMode('add');
    setSelected(null);
    setMode('form');
  };

  const handleEditClick = (student) => {
    setFormMode('edit');
    setSelected(student);
    setMode('form');
  };

  const handleViewClick = (student) => {
    setSelected(student);
    setMode('details');
  };

  const handleDelete = (student) => {
    if(!window.confirm('Delete '+student.name+'?')) return;
    studentService.deleteStudent(student.id)
      .then(()=> {
        alert('Deleted. Click "Load Students" to refresh the list.');
      }).catch(err => {
        alert('Delete failed');
        console.error(err);
      });
  };

  const handleFormSubmit = (payload) => {
    if(formMode === 'add'){
      studentService.addStudent(payload).then(()=>{
        alert('Student added. Click "Load Students" to refresh.');
        setMode('list');
      }).catch(err=>{
        alert('Add failed');
        console.error(err);
      });
    } else {
      studentService.updateStudent(payload.id, payload).then(()=>{
        alert('Student updated. Click "Load Students" to refresh.');
        setMode('list');
      }).catch(err=>{
        alert('Update failed');
        console.error(err);
      });
    }
  };

  return (
    <div style={{fontFamily:'system-ui, Arial',padding:20,maxWidth:900,margin:'0 auto'}}>
      <h1>Student Result App</h1>
      {mode === 'list' && (
        <div>
          <div style={{marginBottom:12}}>
            <button onClick={loadStudents}>Load Students</button>{' '}
            <button onClick={handleAddClick}>Add Student</button>
          </div>
          <StudentList
            students={students}
            onEdit={handleEditClick}
            onDelete={handleDelete}
            onView={handleViewClick}
          />
          <div style={{marginTop:12,color:'#666'}}>Note: After add/edit/delete, click "Load Students" to refresh (no automatic refresh).</div>
        </div>
      )}

      {mode === 'form' && (
        <StudentForm
          mode={formMode}
          initial={selected}
          onCancel={() => setMode('list')}
          onSubmit={handleFormSubmit}
        />
      )}

      {mode === 'details' && selected && (
        <div>
          <button onClick={() => setMode('list')}>Back to List</button>
          <StudentDetails student={selected} />
        </div>
      )}
    </div>
  );
}
